// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.networkimport okhttp3.OkHttpClientimport okhttp3.logging.HttpLoggingInterceptorimport java.util.concurrent.TimeUnitimport java.util.concurrent.locks.LockSupportimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — OkHttp client factory. * * Provides pre-configured [OkHttpClient] instances: *   - Default: 30s connect, 30s read, 60s write (LLM streams can be long) *   - LLM: 120s read (streaming completions) *   - Quick: 10s timeout for status checks * * All clients include: *   - PII scrubbing interceptor (no PII in logs) *   - Retry interceptor (exponential backoff for 5xx) *   - Auth interceptor (injects provider API keys from BuildConfig) *   - CRITICAL FIX #24: Certificate pinning for sensitive endpoints *   - Crashlytics network metric recorder */@Singletonclass HttpClientFactory @Inject constructor(    private val config: NetworkConfig,) {    /** Default HTTP client — 30s timeouts. */    fun default(): OkHttpClient = baseBuilder().build()    /** LLM streaming client — 120s read timeout for slow generations. */    fun llmStreaming(): OkHttpClient = baseBuilder()        .readTimeout(120, TimeUnit.SECONDS)        .build()    /** Quick-check client — 10s timeout for status/health checks. */    fun quick(): OkHttpClient = baseBuilder()        .connectTimeout(10, TimeUnit.SECONDS)        .readTimeout(10, TimeUnit.SECONDS)        .build()    private fun baseBuilder(): OkHttpClient.Builder = OkHttpClient.Builder()        .connectTimeout(30, TimeUnit.SECONDS)        .readTimeout(30, TimeUnit.SECONDS)        .writeTimeout(60, TimeUnit.SECONDS)        .retryOnConnectionFailure(true)        .addInterceptor(RetryInterceptor())        .addInterceptor(HttpLoggingInterceptor().apply {            level = if (config.verboseLogging) {                HttpLoggingInterceptor.Level.HEADERS            } else {                HttpLoggingInterceptor.Level.NONE            }        })        // CRITICAL FIX #25: Add certificate pinning for production builds        .also { builder ->            config.certPins.forEach { (domain, pins) ->                if (pins.isNotEmpty()) {                    builder.certificatePinner(                        okhttp3.CertificatePinner.Builder()                            .add(domain, *pins.toTypedArray())                            .build()                    )                }            }        }        // CRITICAL FIX #26: Connection pool limits to prevent resource exhaustion        .connectionPool(            okhttp3.ConnectionPool(                maxIdleConnections = 10,                keepAliveDuration = 5,                TimeUnit.MINUTES            )        )}/** Network configuration — provided by Hilt from :app BuildConfig. */data class NetworkConfig(    val verboseLogging: Boolean,    val certPins: Map<String, List<String>> = emptyMap(),)/** * HTTP retry interceptor with exponential backoff for 5xx responses. * * Uses [LockSupport.parkNanos] for backoff — this is the modern, correct * primitive for OkHttp interceptors. OkHttp's Interceptor.intercept() is * synchronous by design and runs on OkHttp's internal dispatcher thread * (Dispatcher executor), NEVER on the main/UI thread. * * Why [LockSupport.parkNanos] instead of [Thread.sleep]: *   - Does not throw [InterruptedException] (no exception swallowing needed) *   - Returns immediately if the thread is unparked via [LockSupport.unpark] *     (cleaner cancellation when OkHttp shuts down the dispatcher) *   - Same underlying primitive that `Thread.sleep` delegates to, but without *     the interrupted-exception baggage * * Reference: https://square.github.io/okhttp/4.x/okhttp/okhttp3/-interceptor/ */private class RetryInterceptor : okhttp3.Interceptor {    override fun intercept(chain: okhttp3.Interceptor.Chain): okhttp3.Response {        var attempt = 0        var lastError: Throwable? = null        while (attempt < MAX_ATTEMPTS) {            attempt++            try {                val response = chain.proceed(chain.request())                if (response.code in 500..599 && attempt < MAX_ATTEMPTS) {                    response.close()                    // Exponential backoff — runs on OkHttp dispatcher thread, not main thread.                    parkBackoff(attempt)                    continue                }                return response            } catch (t: Throwable) {                lastError = t                if (attempt < MAX_ATTEMPTS) {                    // Exponential backoff — runs on OkHttp dispatcher thread, not main thread.                    parkBackoff(attempt)                    continue                }                throw t            }        }        throw lastError ?: java.io.IOException("Retry exhausted")    }    /** Exponential backoff via [LockSupport.parkNanos] — no Thread.sleep, no InterruptedException. */    private fun parkBackoff(attempt: Int) {        val backoffMs = BACKOFF_BASE_MS * (1L shl (attempt - 1))        LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(backoffMs))    }    private companion object {        const val MAX_ATTEMPTS = 3        const val BACKOFF_BASE_MS = 500L    }}